//! S-TX-001 (U-2): inputs on which the JVM ends the whole script with an uncatchable error, JVM 3.7.2 vs Rust.
//!
//! Docker-free. `tests/oracle/lf-fatal/expected.tsv` holds, per case of `scripts/gen-lf-fatal.py`, how `daml script
//! --ide-ledger` ended (`ok:<value>` or `fatal:<first line of the error>`; regenerated by `scripts/verify-lf-fatal.sh
//! --update`). Each case is a pure value of `lf-fatal.dar`, evaluated here with `lf-eval`; its outcome is mapped into the
//! same vocabulary and must agree with the JVM's.
use std::path::{Path, PathBuf};

use lf_eval::{Engine, Value, World};

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../tests/oracle/lf-fatal")
}

/// What Daml `show`/the script result prints for a pure result, or the Rust error. A Text that contains NUL is what the
/// JVM refuses when it serializes a result (`Text contains null character`).
fn outcome_of_value(result: Result<Value, String>) -> String {
    match result {
        Ok(Value::Int64(n)) => format!("ok:{n}"),
        Ok(Value::Bool(b)) => format!("ok:{}", if b { "True" } else { "False" }),
        Ok(Value::Text(t)) if t.contains('\0') => "fatal:Text contains null character".to_string(),
        Ok(Value::Text(t)) => format!("ok:{t}"),
        Ok(other) => format!("ok:{other:?}"),
        Err(err) => format!("fatal:{err}"),
    }
}

fn rust_outcome(world: &World, name: &str) -> String {
    let nul = || Value::Text("\0".to_string());
    let holder = |t: Value| Value::Record {
        tycon: None,
        fields: vec![
            ("owner".to_string(), Value::Party("Alice".to_string())),
            ("t".to_string(), t),
        ],
    };
    let alice = ["Alice"];
    // the ledger-level cases (scripts that submit commands); every other case is a pure value named like its script
    match name {
        "createWithNulArgument" => {
            match Engine::new(world).execute_create(&alice, "Fatal:Holder", &holder(nul())) {
                Ok(_) => "ok:created".to_string(),
                Err(e) => format!("fatal:{e}"),
            }
        }
        "createWithoutNul" => match Engine::new(world).execute_create(
            &alice,
            "Fatal:Holder",
            &holder(Value::Text("A".to_string())),
        ) {
            Ok(_) => "ok:created".to_string(),
            Err(e) => format!("fatal:{e}"),
        },
        "createNulInsideAChoice" | "returnNulFromAChoice" => {
            let mut engine = Engine::new(world);
            let cid = engine
                .execute_create(
                    &alice,
                    "Fatal:Holder",
                    &holder(Value::Text("x".to_string())),
                )
                .expect("create Holder")
                .contract_id;
            let choice = if name == "createNulInsideAChoice" {
                "MakeNul"
            } else {
                "KeepNul"
            };
            let empty = Value::Record {
                tycon: None,
                fields: vec![],
            };
            match engine.execute_exercise(&alice, &cid, choice, &empty) {
                Ok(out) => outcome_of_value(Ok(out.result)),
                Err(e) => format!("fatal:{e}"),
            }
        }
        _ => outcome_of_value(
            world
                .eval("Fatal", name.strip_suffix('S').unwrap_or(name), &[])
                .map_err(|e| e.to_string()),
        ),
    }
}

/// The class of an outcome: `ok:<value>`, or the kind of uncatchable error named in the JVM's or Rust's text.
fn kind_of(outcome: &str) -> String {
    let Some(text) = outcome.strip_prefix("fatal:") else {
        return outcome.to_string();
    };
    let lower = text.to_lowercase();
    // the JVM wraps the same MalformedText error in a `RunnerException` when it happens while a submission's result
    // (a created contract, a returned value) is serialized
    if lower.contains("null character") || lower.contains("runnerexception") {
        "fatal:text-with-nul".to_string()
    } else if lower.contains("invalid byte encoding")
        || lower.contains("off the curve")
        || lower.contains("off curve")
    {
        "fatal:crypto-invalid-key-encoding".to_string()
    } else if lower.contains("malformed public key") || lower.contains("malformed key") {
        "fatal:crypto-malformed-key".to_string()
    } else if lower.contains("general error") || lower.contains("generalerror") {
        // an `error`/`fail` raised by Daml library code (the secp256k1 wrapper rejects a signature that is not DER): the
        // exception's type and its message are what both sides name
        let after = lower.rsplit("generalerror").next().unwrap_or("");
        // the JVM adds ` (error category N)` before the message
        let after = after
            .strip_prefix(" (error category")
            .and_then(|r| r.split_once(')'))
            .map_or(after, |(_, rest)| rest);
        // the recorded JVM line is cut at 240 characters (`verify-lf-fatal.sh`), so only the start of the message is compared
        let message: String = after
            .trim_start_matches(':')
            .trim()
            .chars()
            .take(50)
            .collect();
        format!("fatal:daml-error:{message}")
    } else if lower.contains("malformed signature") {
        "fatal:crypto-malformed-signature".to_string()
    } else {
        format!("fatal:other:{text}")
    }
}

#[test]
fn fatal_cases_end_the_same_way_on_both_sides() {
    let world = World::open(&dir().join("lf-fatal.dar")).expect("lf-fatal.dar");
    let expected = std::fs::read_to_string(dir().join("expected.tsv")).expect("expected.tsv");
    assert!(!expected.trim().is_empty(), "expected.tsv is empty");
    let mut matched = 0;
    let mut diffs: Vec<String> = Vec::new();
    for line in expected.lines().filter(|l| !l.is_empty()) {
        let (name, jvm) = line.split_once('\t').unwrap_or((line, ""));
        let rust = rust_outcome(&world, name);
        let (kj, kr) = (kind_of(jvm), kind_of(&rust));
        if std::env::var_os("LF_FATAL_DEBUG").is_some() {
            eprintln!("{name}\n  JVM : {jvm}\n  Rust: {rust}");
        }
        if kj != kr {
            diffs.push(format!("MISMATCH {name}\n  JVM : {jvm}\n  Rust: {rust}"));
            continue;
        }
        matched += 1;
    }
    assert!(
        diffs.is_empty(),
        "{} of {} cases end differently:\n{}",
        diffs.len(),
        diffs.len() + matched,
        diffs.join("\n")
    );
    eprintln!("lf-fatal: {matched} cases end the same way");
}
